"""The robot's face: a head at the end of the camera neck with a face image on its front. Visual only.

    add_face(spec)            # RobotSimulator calls it after the neck and the cameras, before compiling; returns what it built (or None)
    Face(model).set_smile(b)  # the episode runner shows the neutral face normally and the smile once the success check has passed
    with face.facing(data, cam): ...   # the viewer and the composite view draw the head turned toward their camera (render time only, see facing())
    set_enabled(False)        # process-wide switch (the --no-face options); None goes back to FACE_CFG["enabled"]

The head is one ellipsoid (robot_specs.FACE_CFG: "head_radii") attached to the body that carries the eagle camera, placed so that the camera sits just in front of
and above the head's centre, outside the surface: on the forehead, never covered. The ellipsoid has a texture made from the face image: MuJoCo maps a 2D texture on
an ellipsoid by longitude and latitude (the seam at the geom's local +x, longitude growing from +x towards +y, the first row at the +z pole), so the image is warped
onto that layout once, with the front of the head (local -x) at the middle of the texture. The neutral and the smile images are two materials; switching the face
is changing the geom's material index (model.geom_matid), which needs no new upload to the graphics context.

Visual only, by construction:
  * mass 0 and density 0 (the body's mass and inertia do not change), contype and conaffinity 0 (no contact);
  * drawing the textured head makes MuJoCo's renderer lose the shadows of the next render (and of every geom drawn after the head in the same render); the face material is
    0.99 opaque so that the head is drawn after the opaque geoms, and settle_renderer() takes the hit of the next render for a millisecond;
  * geom group FACE_CFG["group"] (5): the cameras of the policy (src/cameras.CameraRig, the operator insets, the replay) use MuJoCo's default groups 0-2 and never
    draw it, so no policy image contains the head. The window viewer and the composite picture of the notebook videos switch the group on (show_face_group());
  * the replay fingerprint (src/run_record.model_hash) leaves the head, its materials and its textures out, so a recording verifies the same with the face
    images present, missing, or the face off.
If an image is missing the head is plain (the grey of the images' margin) and one line is printed. No error.
"""

from contextlib import contextmanager
from pathlib import Path

import cv2
import mujoco
import numpy as np

from src import robot_specs
from src.cameras import look_at_quat

PROJECT_ROOT = Path(__file__).resolve().parent.parent
HEAD_GEOM = "face_head"
_override = [None]                  # set_enabled(): None = FACE_CFG["enabled"]
_noticed = set()                    # the missing-image notices already printed in this process


def set_enabled(value):
    """Turns the face on or off for every model built after this call (the --no-face command-line options).

    Args:
        value (bool or None): True or False to force it, None to follow robot_specs.FACE_CFG["enabled"].
    """
    _override[0] = value


def get_override():
    """Gives the process-wide switch set by set_enabled().

    Returns:
        bool or None: The forced value, or None when FACE_CFG["enabled"] decides.
    """
    return _override[0]


def is_enabled(cfg=None):
    """Tells whether the face is built into new models.

    Args:
        cfg (dict or None): The face configuration. Defaults to robot_specs.FACE_CFG.

    Returns:
        bool: The process-wide switch if set_enabled() was called with a bool, else cfg["enabled"].
    """
    cfg = cfg or robot_specs.FACE_CFG
    return bool(cfg["enabled"]) if _override[0] is None else bool(_override[0])


def show_face_group(option, cfg=None):
    """Makes a window or composite view draw the face (the policy cameras never call this).

    Args:
        option (mujoco.MjvOption): The visualisation options of the view; changed.
        cfg (dict or None): The face configuration. Defaults to robot_specs.FACE_CFG.
    """
    option.geomgroup[(cfg or robot_specs.FACE_CFG)["group"]] = 1


def settle_renderer(context, scene):
    """Absorbs the renderer's one-render hangover after it has drawn the textured head.

    The first mjr_render after a render that drew the textured head loses its shadows (MuJoCo leaves some texture state of the head behind; the render after that is
    normal). In the viewer's frame loop that first render is the eagle camera's, so its picture came out about 1.4 times too bright: every floor and bench top. A render
    of one geom with shadows on, into a 1 x 1 offscreen viewport, takes the hit instead and costs about a millisecond (an empty scene, or one without shadows, does
    not help, a full scene costs 200 ms). Call it right after the render that draws the head, the picture already read or drawn; the graphics context must be current.

    Args:
        context (mujoco.MjrContext): The rendering context (it must have an offscreen buffer, as the camera rig's has).
        scene (mujoco.MjvScene): The scene that was just rendered; it is cut down to its first geom and its reflection flag is off while this renders, so it must be
            refilled by mjv_updateScene before it is used again.
    """
    shadow, reflection = scene.flags[mujoco.mjtRndFlag.mjRND_SHADOW], scene.flags[mujoco.mjtRndFlag.mjRND_REFLECTION]
    scene.flags[mujoco.mjtRndFlag.mjRND_SHADOW], scene.flags[mujoco.mjtRndFlag.mjRND_REFLECTION] = 1, 0
    scene.ngeom = min(scene.ngeom, 1)
    mujoco.mjr_setBuffer(mujoco.mjtFramebuffer.mjFB_OFFSCREEN, context)
    mujoco.mjr_render(mujoco.MjrRect(0, 0, 1, 1), scene, context)
    mujoco.mjr_setBuffer(mujoco.mjtFramebuffer.mjFB_WINDOW, context)
    scene.flags[mujoco.mjtRndFlag.mjRND_SHADOW], scene.flags[mujoco.mjtRndFlag.mjRND_REFLECTION] = shadow, reflection


def face_texture(image_bgr, cfg=None):
    """Warps a face image onto the longitude / latitude layout of the head ellipsoid's texture.

    The head's front (local -x) is in the middle of the texture; a viewer in front of the face sees the image upright and not mirrored. Everything outside the
    rectangle the image covers (face_size, centred face_center_up above the head's centre) is the head's colour.

    Args:
        image_bgr (numpy.ndarray): The face image, shape (rows, columns, 3), OpenCV colour order. Its margin should be the grey of cfg["color"].
        cfg (dict or None): The face configuration. Defaults to robot_specs.FACE_CFG.

    Returns:
        numpy.ndarray: RGB texture of shape (texture height, texture width, 3), dtype uint8, row 0 at the +z pole.
    """
    cfg = cfg or robot_specs.FACE_CFG
    tw, th = cfg["texture_size"]
    a, b, c = cfg["head_radii"]
    lon = 2 * np.pi * (np.arange(tw) + 0.5) / tw
    colat = np.pi * (np.arange(th) + 0.5) / th
    L, C = np.meshgrid(lon, colat)
    px, py, pz = a * np.sin(C) * np.cos(L), b * np.sin(C) * np.sin(L), c * np.cos(C)      # the surface point in the geom's frame
    ih, iw = image_bgr.shape[:2]
    fw, fh = cfg["face_size"]
    # a viewer facing the front (looking along local +x, up = local +z) has local -y on the right
    map_x = (iw * (0.5 + (-py) / fw)).astype(np.float32)
    map_y = (ih * (0.5 - (pz - cfg["face_center_up"]) / fh)).astype(np.float32)
    grey_bgr = tuple(int(v) for v in cfg["color"][::-1])
    out = cv2.remap(image_bgr, map_x, map_y, cv2.INTER_LINEAR, borderMode=cv2.BORDER_CONSTANT, borderValue=grey_bgr)
    out[px >= 0] = grey_bgr                                                                 # the back half of the head
    return np.ascontiguousarray(out[:, :, ::-1])


def head_frame(camera_spec, cfg=None):
    """Gives the head's pose in the body that carries the eagle camera.

    Args:
        camera_spec (dict): The eagle camera's specification (robot_specs.CAMERA_SPECS entry: "pos", "look_at", "up" in its parent body's frame).
        cfg (dict or None): The face configuration. Defaults to robot_specs.FACE_CFG.

    Returns:
        tuple: (centre (3,), quaternion (w, x, y, z)) of the head ellipsoid in the parent body's frame. The ellipsoid's local axes are x = backwards, y = to the
        camera's right, z = up (the camera's up), so its front is local -x.
    """
    cfg = cfg or robot_specs.FACE_CFG
    pos = np.asarray(camera_spec["pos"], float)
    q = look_at_quat(pos, camera_spec["look_at"], camera_spec["up"])
    m = np.zeros(9)
    mujoco.mju_quat2Mat(m, q)
    m = m.reshape(3, 3)
    right, up, fwd = m[:, 0], m[:, 1], -m[:, 2]
    centre = pos - up * cfg["camera_above_center"] - fwd * cfg["camera_forward_of_center"]
    rot = np.column_stack([-fwd, right, up])
    quat = np.zeros(4)
    mujoco.mju_mat2Quat(quat, rot.flatten())
    return centre, quat


def add_face(spec, cfg=None, camera_specs=None):
    """Adds the head (and its face materials) to the specification.

    Args:
        spec (mujoco.MjSpec): The robot's specification with the neck, not yet compiled; changed.
        cfg (dict or None): The face configuration. Defaults to robot_specs.FACE_CFG.
        camera_specs (list of dict or None): The camera specifications. Defaults to robot_specs.CAMERA_SPECS; the one named "eagle_cam" sets where the head is.

    Returns:
        dict or None: None if the face is off or the model has no eagle camera body; else {"textured" (bool: both images found), "materials" (names)}.
    """
    cfg = cfg or robot_specs.FACE_CFG
    if not is_enabled(cfg):
        return None
    eagle = next((cs for cs in (camera_specs or robot_specs.CAMERA_SPECS) if cs["name"] == "eagle_cam"), None)
    body = spec.body(eagle["parent"]) if eagle else None
    if body is None:
        return None
    centre, quat = head_frame(eagle, cfg)
    folder = PROJECT_ROOT / cfg["image_dir"]
    images = {k: cv2.imread(str(folder / cfg[k])) for k in ("neutral", "smile")}
    textured = all(im is not None for im in images.values())
    kwargs = {}
    if textured:
        tw, th = cfg["texture_size"]
        for k, im in images.items():
            tex = spec.add_texture(name=f"face_{k}", type=mujoco.mjtTexture.mjTEXTURE_2D, width=tw, height=th, nchannel=3)
            tex.data = face_texture(im, cfg).tobytes()
            mat = spec.add_material(name=f"face_{k}")
            mat.textures[mujoco.mjtTextureRole.mjTEXROLE_RGB] = f"face_{k}"
            # 0.99 on purpose: MuJoCo draws transparent geoms in a later pass. A textured geom drawn among the opaque ones makes the renderer lose the
            # shadows of everything drawn after it on this VM (every floor and bench top in the viewer came out about 1.4 times too bright).
            mat.rgba = [1.0, 1.0, 1.0, 0.99]
            mat.specular, mat.shininess = 0.05, 0.05
        kwargs["material"] = "face_neutral"
    else:
        missing = [cfg[k] for k in ("neutral", "smile") if images[k] is None]
        if tuple(missing) not in _noticed:
            _noticed.add(tuple(missing))
            print(f"  Note: face image(s) not found in {cfg['image_dir']} ({', '.join(missing)}): using a plain head")
        kwargs["rgba"] = [v / 255.0 for v in cfg["color"]] + [1.0]
    body.add_geom(name=HEAD_GEOM, type=mujoco.mjtGeom.mjGEOM_ELLIPSOID, size=list(cfg["head_radii"]), pos=list(centre), quat=list(quat),
                  group=cfg["group"], contype=0, conaffinity=0, mass=0.0, density=0.0, **kwargs)
    return {"textured": textured, "materials": ["face_neutral", "face_smile"] if textured else []}


class Face:
    """The face of a compiled model: shows the neutral or the smiling image.

    Attributes:
        present (bool): The model has a head.
        textured (bool): It has both images (otherwise the head is plain and set_smile() does nothing).
        smiling (bool): The smile is showing.
    """

    def __init__(self, model):
        """Looks the head and its materials up in the model.

        Args:
            model (mujoco.MjModel): The compiled model.
        """
        self.model = model
        self.geom = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_GEOM, HEAD_GEOM)
        self.present = self.geom >= 0
        self.mat = {k: mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_MATERIAL, f"face_{k}") for k in ("neutral", "smile")}
        self.textured = self.present and all(v >= 0 for v in self.mat.values())
        self.smiling = False

    def set_smile(self, on):
        """Shows the smile (True) or the neutral face (False).

        Args:
            on (bool): Whether to smile. Does nothing if the head is plain or absent.
        """
        self.smiling = bool(on)
        if self.textured:
            self.model.geom_matid[self.geom] = self.mat["smile" if on else "neutral"]

    @contextmanager
    def facing(self, data, cam):
        """Turns the head's front toward a free camera while a view is drawn (render time only).

        Overwrites data.geom_xmat of the head: the front (local -x) points from the head's centre at the camera, the head's up (local z) is the world's up as far as it
        can be (the head's own up if the camera is straight above or below). The model is not touched; the head has no mass and no contact, no state is hashed from it, and
        the policy cameras never draw it, so nothing but the picture of the view this wraps changes. The previous matrix is put back on exit. Does nothing without a head.

        Args:
            data (mujoco.MjData): The state about to be drawn; its geom_xpos and geom_xmat must be current (mj_forward or mj_step has run).
            cam (mujoco.MjvCamera): The free camera of the view (type free: lookat, distance, azimuth, elevation).

        Yields:
            None
        """
        if not self.present:
            yield
            return
        saved = data.geom_xmat[self.geom].copy()
        data.geom_xmat[self.geom] = facing_matrix(data.geom_xpos[self.geom], free_camera_position(cam), saved.reshape(3, 3)[:, 2]).flatten()
        try:
            yield
        finally:
            data.geom_xmat[self.geom] = saved


def free_camera_position(cam):
    """Gives where a free MuJoCo camera is (it looks at cam.lookat from cam.distance along its azimuth and elevation).

    Args:
        cam (mujoco.MjvCamera): A free camera.

    Returns:
        numpy.ndarray: The camera's position in the world, shape (3,).
    """
    az, el = np.radians(cam.azimuth), np.radians(cam.elevation)
    forward = np.array([np.cos(el) * np.cos(az), np.cos(el) * np.sin(az), np.sin(el)])
    return np.asarray(cam.lookat, float) - cam.distance * forward


def facing_matrix(centre, target, fallback_up):
    """Gives the head orientation whose front looks at a point, with its up as close to the world's up as possible.

    Args:
        centre (array-like): The head's centre in the world, shape (3,).
        target (array-like): The point to face (the camera), shape (3,).
        fallback_up (array-like): The up to keep when the target is straight above or below the head, shape (3,).

    Returns:
        numpy.ndarray: Rotation matrix (3, 3), columns the head's local x (backwards), y and z (up), so the front, local -x, points at the target.
    """
    f = np.asarray(target, float) - np.asarray(centre, float)
    f = f / max(np.linalg.norm(f), 1e-9)
    up = np.array([0.0, 0.0, 1.0])
    z = up - np.dot(up, f) * f
    if np.linalg.norm(z) < 1e-6:
        z = np.asarray(fallback_up, float) - np.dot(fallback_up, f) * f
    z = z / np.linalg.norm(z)
    x = -f
    return np.column_stack([x, np.cross(z, x), z])
